  db:            { compose: db, ports: { main: { default: 5432, env: DB_PORT } } }
  cache:         { compose: redis, ports: { main: { default: 6380, env: REDIS_PORT } } }
  control-plane: { run: "pnpm dev", cwd: apps/control-plane, depends_on: [db, cache],
                   env: { NODE_ENV: development },
